import{_ as l,l as i,o as e,c as s,v as r,p as n,x as o,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"内存气球","description":"","frontmatter":{"title":"内存气球","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-balloon.md","filePath":"cs/memory-balloon.md","lastUpdated":1789023840000}'),h={name:"cs/memory-balloon.md"};function m(u,a,f,E,_,B){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="内存气球" tabindex="-1">内存气球 <a class="header-anchor" href="#内存气球" aria-label="Permalink to &quot;内存气球&quot;">​</a></h1><div class="epigraph"><p>气球驱动在客户里申请页并钉住还给 hypervisor：宿主回收这些框，客户 RSS 看起来仍在，实际可被超售。</p><footer>—— 据 Waldspurger 对 ESX 气球的论述；virtio-balloon；[memcg](/cs/memcg) 与 [KSM](/cs/ksm) 为宿主侧对照</footer></div><p><a href="/cs/clock-virtualization">时钟</a> 处理偷时间。内存超售另一钩：<strong>气球</strong>。缺口是客户配合 vs 宿主 <a href="/cs/userfaultfd">userfaultfd</a> 回收。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>inflate：客户分配、告诉宿主 pfn 列表，宿主可拆 EPT。deflate：还页给客户。缺口：客户 OOM vs 宿主要内存；与 THP 拆页。本课不把每个 hypervisor 的目标 RSS 算法写完。</p><p><span class="marginnote">free page hinting 是气球亲戚：客户报告空闲。对象是合作回收，不是恶意。 </span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宿主发 inflat 请求 → 客户气球驱动 → 页从客户 buddy 拿走。对照 memcg：限 QEMU 进程；气球限客户内。对照 <a href="/cs/zswap">zswap</a>：客户自己也可 swap。对照 热插拔：balloon 更动态、非物理条。</p>',8)),(e(),n(d,null,{default:o(()=>[c(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HV%5B%22%E5%AE%BF%E4%B8%BB%E8%A6%81%E5%86%85%E5%AD%98%22%5D%20--%3E%20INF%5B%22inflate%20%E6%B0%94%E7%90%83%22%5D%0A%20%20INF%20--%3E%20PIN%5B%22%E5%AE%A2%E6%88%B7%E9%92%89%E9%A1%B5%E4%BA%A4%E8%BF%98%22%5D%0A%20%20PIN%20--%3E%20EPT%5B%22%E5%AE%BF%E4%B8%BB%E5%9B%9E%E6%94%B6%20HPA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>气球把超售从「宿主硬夺 EPT 导致客户随机缺页」变成「客户分配器参与」，更少破坏。不合作的客户会被硬回收或 swap 宿主。不要写成云规格谎言。与 <a href="/cs/cgroup-cpu-sched">cgroup</a> 正交。</p><p>气球过大等于客户自己 OOM。</p><p>实现上：inflate 过猛等于在客户里制造 OOM。free page reporting 让宿主回收空闲而不必气球。与 KSM 一起用时，气球页不应被合并成假共享。 读法上只引用<a href="/cs/clock-virtualization">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>内存气球</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 stats。不保证 Windows 气球驱动行为。下一课把整机搬走：热迁移。</p><p>版本字段会变，课序钉的是机制对象「内存气球」，不是某一主线内核的结构体名。 后课默认：可合作收回客户页。不停机迁到另一宿主，下一课热迁移。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>气球让客户自己拿出页给宿主回收。</li><li>是内存超售的合作通道。</li><li>热迁移是下一课。</li><li>出处：Waldspurger；virtio-balloon；KVM。</li></ul>',11))])}const A=l(h,[["render",m]]);export{g as __pageData,A as default};
